verifyCmd:
node <<'VERIFYJS'
const p = require('./parseCsv.js');
const eq = (a, b, m) => { if (JSON.stringify(a) !== JSON.stringify(b)) { console.error(m, JSON.stringify(a)); process.exit(1); } };
eq(p(''), [], 'empty');
eq(p('a,b\n'), [['a','b']], 'trailing LF must not add a row');
eq(p('a,b\r\nc,d'), [['a','b'],['c','d']], 'CRLF');
eq(p('"a,b",c'), [['a,b','c']], 'quoted comma');
eq(p('"a""b"'), [['a"b']], 'escaped quote');
eq(p('"a\nb",c'), [['a\nb','c']], 'embedded newline');
eq(p('\n'), [['']], 'lone separator is one empty field');
eq(p('a,,b'), [['a','','b']], 'empty middle field');
eq(p('"",x'), [['','x']], 'empty quoted field');
try { p('"abc'); console.error('no throw on unterminated'); process.exit(1); } catch (e) {}
console.log('ok');
VERIFYJS
